import copy


def normalize_chain(records):
    if not isinstance(records, list):
        raise TypeError("records must be a list")
    result = []
    for record in records:
        if not isinstance(record, dict):
            raise TypeError("record must be a dict")
        if "subject" not in record or "issuer" not in record:
            raise ValueError("missing chain field")
        if not isinstance(record["subject"], str) or not record["subject"]:
            raise ValueError("invalid subject")
        if not isinstance(record["issuer"], str) or not record["issuer"]:
            raise ValueError("invalid issuer")
        result.append(copy.deepcopy(record))
    result.reverse()
    return result

